#include <iostream>
#include <memory>
#include <optional>
#include <utility>

template <typename T>
class Stack {
private:
    struct Node {
        T data;
        std::unique_ptr<Node> next;
        Node(T val, std::unique_ptr<Node> nextNode)
            : data(std::move(val)), next(std::move(nextNode)) {}
    };

    std::unique_ptr<Node> topNode{nullptr};

public:
    Stack() = default;
    ~Stack() = default;

    // Push puts node at top (Step 1, 2, 3 combined safely)
    void push(T val) {
        topNode = std::make_unique<Node>(std::move(val), std::move(topNode));
    }

    // Pop removes top node and returns value (5 steps)
    std::optional<T> pop() {
        if (!topNode) {
            return std::nullopt;
        }
        T val = std::move(topNode->data);
        topNode = std::move(topNode->next); // automatically frees old top
        return val;
    }

    bool isEmpty() const {
        return topNode == nullptr;
    }

    void print() const {
        if (!topNode) {
            std::cout << "The stack is empty.\n";
            return;
        }
        std::cout << "The stack is:\n";
        for (const Node* curr = topNode.get(); curr != nullptr; curr = curr->next.get()) {
            std::cout << curr->data << " --> ";
        }
        std::cout << "NULL\n";
    }
};

int main() {
    Stack<int> s;
    int val;
    // Read values to push
    if (std::cin >> val) s.push(val);
    if (std::cin >> val) s.push(val);
    if (std::cin >> val) s.push(val);

    s.print();

    auto popped = s.pop();
    if (popped) {
        std::cout << "The popped value is " << *popped << ".\n";
    }
    s.print();

    return 0;
}

#include <iostream>
#include <memory>
#include <optional>

class CharQueue {
private:
    struct Node {
        char data;
        std::unique_ptr<Node> next{nullptr};
        explicit Node(char c) : data(c), next(nullptr) {}
    };

    std::unique_ptr<Node> head{nullptr};
    Node* tail{nullptr}; // Raw pointer non-owning observer for O(1) enqueue

public:
    CharQueue() = default;
    ~CharQueue() = default;

    bool isEmpty() const {
        return head == nullptr;
    }

    // Enqueue at tail (O(1))
    void enqueue(char val) {
        auto newNode = std::make_unique<Node>(val);
        Node* rawNew = newNode.get();

        if (isEmpty()) {
            head = std::move(newNode);
            tail = rawNew;
        } else {
            tail->next = std::move(newNode);
            tail = rawNew;
        }
    }

    // Dequeue from head (O(1))
    std::optional<char> dequeue() {
        if (isEmpty()) {
            return std::nullopt;
        }
        char val = head->data;
        head = std::move(head->next);
        if (head == nullptr) {
            tail = nullptr; // Reset tail when queue becomes empty
        }
        return val;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "Queue is empty.\n";
            return;
        }
        std::cout << "The queue is:\n";
        for (const Node* curr = head.get(); curr != nullptr; curr = curr->next.get()) {
            std::cout << curr->data << " --> ";
        }
        std::cout << "NULL\n";
    }
};

int main() {
    CharQueue q;
    char ch;
    // Read characters and enqueue
    while (std::cin >> ch) {
        q.enqueue(ch);
    }

    q.print();

    auto val = q.dequeue();
    if (val) {
        std::cout << *val << " has been dequeued.\n";
    }
    q.print();

    return 0;
}
